components.css:
.ds-sample {font-family:var(--font-body, Inter),system-ui,-apple-system,sans-serif; color:var(--sb-ink,#12234b);}
.ds-primary,
.ds-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  min-height: 52px;
  padding: 14px 25px;
  border-radius: 9px;
  font-weight: 700;
  font-size: 15px;
  text-decoration: none;
  transition:
    background 0.18s,
    box-shadow 0.18s;
  color: white;
  background: var(--sb-blue);
  border: 0;
}
.ds-primary:hover {
  background: #193ac2;
  box-shadow: 0 5px 15px #244ceb20;
}
.ds-hero-actions .ds-primary {
  min-height: 58px;
  padding: 16px 28px;
  font-size: 17px;
}
.ds-composer .ds-primary {
  font-size: 12px;
  min-height: 43px;
  padding: 12px 15px;
  width: 100%;
  gap: 8px;
}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible {outline:3px solid var(--sb-blue,#244ceb);outline-offset:4px;} button {cursor:pointer;} button:disabled {opacity:.5;cursor:not-allowed;}
@media(prefers-reduced-motion:no-preference){.ds-primary>svg{transition:transform 180ms ease-out}.ds-primary:hover>svg{transform:translateX(3px)}.ds-primary:active{transform:scale(.985)}}
@media(prefers-reduced-motion:reduce){*{transition-duration:.01ms!important;animation-duration:.01ms!important}}

