.ds-faq details {
  border-bottom: 1px solid var(--sb-line);
}
.ds-faq details:first-child {
  border-top: 1px solid var(--sb-line);
}
.ds-faq summary {
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  font-size: 15px;
  font-weight: 600;
  padding: 22px 0;
  cursor: pointer;
  line-height: 1.5;
}
.ds-faq summary::-webkit-details-marker {
  display: none;
}
.ds-faq summary > span {
  flex-shrink: 0;
  color: var(--sb-blue);
  transition: transform 0.2s;
}
.ds-faq details[open] summary > span {
  transform: rotate(45deg);
}
.ds-faq details p {
  color: var(--sb-muted);
  font-size: 14px;
  line-height: 1.8;
  padding: 0 28px 24px 0;
  margin: 0;
}
